from openpyxl import load_workbook

PATH = "budget.xlsx"
wb = load_workbook(PATH, data_only=True)

expense_hints = ("amount", "cost", "expense", "spend", "price", "paid", "value", "total")
grand_total = 0.0

for ws in wb.worksheets:
    rows = list(ws.iter_rows(values_only=True))
    rows = [r for r in rows if any(c is not None and str(c).strip() != "" for c in r)]
    if not rows:
        continue
    header = [str(c).strip().lower() if c is not None else "" for c in rows[0]]
    data = rows[1:]

    amount_cols = [i for i, h in enumerate(header) if any(t in h for t in expense_hints)]
    sheet_total = 0.0
    if amount_cols:
        for row in data:
            for i in amount_cols:
                if i < len(row) and isinstance(row[i], (int, float)):
                    sheet_total += row[i]
    else:
        for row in data:
            for cell in row:
                if isinstance(cell, (int, float)):
                    sheet_total += cell
    print(f"sheet={ws.title!r} header={header}")
    print(f"  amount_cols={amount_cols} sheet_total={sheet_total}")
    grand_total += sheet_total

print(f"GRAND_TOTAL={grand_total}")

